    "use strict";


    function strrep(str, n) {
	var i, s = '';

	for ( i = 0; i < n; i++ ) { s += str; }

	return s;
    }

    function template(text,data) {
        return text.replace(/\{([a-zA-Z0-9_.%]*)\}/g,
	                    function(m,key){
	                        var type, prec, widt = 0, fmt, i;
	                        var val = data;
	                        
	                        key = key.split("%");

	                        if ( key.length <= 1 ) {
		                    fmt = "%s";
	                        } else {
		                    fmt = key[1];
	                        }

	                        key = key[0];
	                        key = key.split(".");

	                        for ( i = 0; i < key.length; i++ ) {
		                    if ( val.hasOwnProperty(key[i]) ) {
		                        val = val[key[i]];
		                    } else {
		                        return "";
		                    }
	                        }

	                        type = fmt.substring(fmt.length-1);
	                        prec = fmt.substring(0, fmt.length-1);

	                        prec = prec.split(".");

	                        widt = prec[0] | 0;
	                        prec = prec[1] | 0;

	                        switch ( type ) {
	                        case "s":
		                    val = val.toString();
		                    break;
	                        case "f":
		                    val = val.toFixed(prec);
		                    break;
	                        case "d":
		                    val = val.toFixed(0);
		                    break;
	                        }

	                        if ( widt !== 0 && widt > val.length ) {
		                    if ( widt > 0 ) {
		                        val = strrep(" ", widt-val.length) + val;
		                    } else {
		                        val = val + strrep(" ", widt-val.length);
		                    }
	                        }

	                        return val;
	                    }
                           );
    }

    module.exports = template;

